import type { FastifyInstance } from 'fastify';
import { z } from 'zod';
import { CATEGORIES } from '@honey/core';
import { HttpError, requireStaff, type AuthContext } from '../auth.js';
import type { LoyaltyService, Repository } from '@honey/service';

const uzs = z.number().int().nonnegative().max(Number.MAX_SAFE_INTEGER);

const purchaseBody = z
  .object({
    clientId: z.string().min(1),
    /** Generated by the staff UI once per order (e.g. UUID); retries reuse it. */
    idempotencyKey: z.string().min(8).max(100),
    channel: z.enum(['store', 'delivery']).default('store'),
    /** Either `lines` or a single `amount` (treated as flowers). */
    lines: z.array(z.object({ category: z.enum(CATEGORIES), amount: uzs })).min(1).optional(),
    amount: uzs.positive().optional(),
    redeemPoints: uzs.optional(),
    useRewardId: z.string().nullish(),
  })
  .refine((b) => !!b.lines !== (b.amount !== undefined), { message: 'pass exactly one of `lines` or `amount`' });

const redeemBody = z.object({
  clientId: z.string().min(1),
  idempotencyKey: z.string().min(8).max(100),
  points: uzs.optional(),
  orderAmount: uzs.positive().optional(),
  rewardId: z.string().nullish(),
  reason: z.string().max(500).nullish(),
});

const reverseBody = z.object({ reason: z.string().trim().min(3).max(500) });

export function staffRoutes(app: FastifyInstance, deps: { repo: Repository; service: LoyaltyService; auth: AuthContext }) {
  app.post('/staff/purchases', async (req, reply) => {
    const staff = await requireStaff(req, deps.repo, deps.auth);
    const b = purchaseBody.parse(req.body);
    const lines = b.lines ?? [{ category: 'flowers' as const, amount: b.amount! }];
    const res = await deps.service.purchase(staff, { ...b, lines });
    reply.code(res.replayed ? 200 : 201);
    return res;
  });

  app.post('/staff/redeem', async (req) => {
    const staff = await requireStaff(req, deps.repo, deps.auth);
    return deps.service.redeem(staff, redeemBody.parse(req.body));
  });

  // The brief lists "cancel with reason" for florists and managers alike;
  // restrict here (e.g. ['manager', 'owner']) if the client decides otherwise.
  app.post<{ Params: { id: string } }>('/staff/purchases/:id/reverse', async (req) => {
    const staff = await requireStaff(req, deps.repo, deps.auth, ['florist', 'manager', 'owner']);
    const { reason } = reverseBody.parse(req.body);
    return deps.service.reverse(staff, { purchaseId: req.params.id, reason });
  });

  app.get('/staff/clients/search', async (req) => {
    await requireStaff(req, deps.repo, deps.auth);
    const { phone } = z.object({ phone: z.string().min(1) }).parse(req.query);
    if (phone.replace(/\D/g, '').length < 4) throw new HttpError(400, 'INVALID_INPUT', 'enter at least 4 digits of the phone');
    return { clients: await deps.service.searchByPhone(phone) };
  });
}
